#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int tenths(const string&s){
 int p=0,whole=0,f=0,sign=1;
 if(s.size()&&(s[0]=='-'||s[0]=='+')){if(s[0]=='-')sign=-1;p++;}
 while(p<(int)s.size()&&s[p]>='0'&&s[p]<='9'){whole=whole*10+s[p]-'0';p++;}
 if(p<(int)s.size()&&s[p]=='.'&&p+1<(int)s.size())f=s[p+1]-'0';
 return sign*(whole*10+f);
}
string score(int n){if(n<0)return "-"+score(-n);return to_string(n/10)+"."+to_string(n%10);}
pair<string,int> parse(const string&s){size_t e=s.find_last_not_of(' ');string t=s.substr(0,e+1);size_t p=t.find_last_of(' ');return {t.substr(0,p),tenths(t.substr(p+1))};}
int main(){int n;cin>>n;string discard;getline(cin,discard);long long sum=0;for(int i=0;i<n;i++){string s;getline(cin,s);sum+=parse(s).second;}
long long cents=(20*sum+n)/(2*n);cout<<cents/100<<'.';if(cents%100<10)cout<<'0';cout<<cents%100<<'\n';}
